(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[194],{5194:(e,o,t)=>{Promise.resolve().then(t.bind(t,6027))},6027:(e,o,t)=>{"use strict";t.d(o,{default:()=>h});var a=t(5155),s=t(2115),r=t(5192);let i={ru:{consent:{title:"СОГЛАСИЕ НА ОБРАБОТКУ ПЕРСОНАЛЬНЫХ ДАННЫХ",updated:"Редакция от 03 октября 2026 года.",intro:["Настоящим я, являясь пользователем сайта iroxtech.ru (далее — \xabСайт\xbb), свободно, своей волей и в своем интересе даю конкретное, предметное, информированное, сознательное и однозначное согласие оператору персональных данных сайта iroxtech.ru, e-mail: hello@iroxtech.ru (далее — \xabОператор\xbb), на обработку моих персональных данных на следующих условиях."],sections:[{h:"1. Цели обработки персональных данных",blocks:["Персональные данные обрабатываются для:",["получения и рассмотрения моего обращения;","связи со мной по поводу направленного обращения;","предварительной оценки возможности роботизации и/или автоматизации указанной мной производственной, складской или логистической операции;","определения возможного типа робототехнического решения;","уточнения исходных данных, необходимых для проведения оценки;","подготовки и направления предварительной оценки, предложения или иной информации по моему обращению;","организации дальнейшего взаимодействия и переговоров по моей инициативе."],"Настоящее согласие не предусматривает использование моих контактных данных для рекламных рассылок, не связанных с направленным мной обращением."]},{h:"2. Перечень персональных данных",blocks:["Согласие распространяется на следующие персональные данные, которые я самостоятельно предоставляю посредством формы на Сайте:",["имя;","наименование компании и сведения о месте работы, если они указаны;","номер телефона;","идентификатор или имя пользователя в Telegram, если указан;","адрес электронной почты;","сведения, содержащиеся в текстовом описании операции;","иные персональные данные, которые я добровольно укажу в обращении;","персональные данные, которые могут содержаться в добровольно загруженном мной видеофайле."]]},{h:"3. Загружаемые видеофайлы",blocks:["Я понимаю, что направляемый мной видеофайл может содержать изображения людей, голоса или иные сведения, относящиеся к физическим лицам.","Я подтверждаю, что при передаче Оператору материалов, содержащих персональные данные третьих лиц, у меня имеются необходимые законные основания для такой передачи.","Оператор использует полученные видеофайлы в целях анализа производственной, складской или логистической операции и подготовки предварительной оценки возможности ее роботизации и/или автоматизации.","Оператор не осуществляет обработку изображений лиц или записей голоса, содержащихся в видео, в целях установления личности человека, если иное отдельно не согласовано с соответствующим субъектом персональных данных и не предусмотрено законом."]},{h:"4. Действия с персональными данными",blocks:["Я даю согласие на совершение Оператором следующих действий с моими персональными данными:","сбор, запись, систематизация, накопление, хранение, уточнение (обновление, изменение), извлечение, использование, предоставление лицам, привлекаемым Оператором для технического обеспечения работы Сайта и обработки обращения, блокирование, удаление и уничтожение.","Обработка может осуществляться как с использованием средств автоматизации, так и без использования таких средств."]},{h:"5. Передача данных и поручение обработки",blocks:["Оператор вправе поручить обработку персональных данных лицам, обеспечивающим функционирование Сайта, хостинга, информационных систем, электронной почты, хранения загружаемых файлов и обработки обращений, в объеме, необходимом для выполнения соответствующих функций и при соблюдении требований законодательства Российской Федерации о персональных данных.","Передача персональных данных иным лицам осуществляется при наличии законного основания."]},{h:"6. Срок обработки",blocks:["Персональные данные обрабатываются до достижения целей, для которых они были получены, либо до отзыва настоящего согласия, если отсутствуют иные предусмотренные законодательством Российской Федерации основания для продолжения их обработки.","При достижении целей обработки, отзыве согласия либо наступлении иных предусмотренных законом оснований обработка прекращается, а персональные данные уничтожаются или обезличиваются в порядке и сроки, предусмотренные законодательством Российской Федерации."]},{h:"7. Отзыв согласия",blocks:["Я вправе отозвать настоящее согласие путем направления заявления Оператору по адресу электронной почты:","hello@iroxtech.ru","В заявлении рекомендуется указать сведения, позволяющие Оператору определить, к каким персональным данным и обращению относится отзыв.","После получения отзыва Оператор прекращает обработку персональных данных и уничтожает их в порядке и сроки, предусмотренные законодательством Российской Федерации, если отсутствуют законные основания для продолжения обработки без согласия субъекта."]},{h:"8. Подтверждение согласия",blocks:["Проставляя соответствующую отметку (checkbox) в форме на Сайте и отправляя форму, я подтверждаю, что ознакомился с настоящим Согласием, понимаю его содержание и выражаю согласие на обработку моих персональных данных на указанных условиях."]}]},privacy:{title:"ПОЛИТИКА В ОТНОШЕНИИ ОБРАБОТКИ ПЕРСОНАЛЬНЫХ ДАННЫХ",updated:"Редакция от 03 октября 2026 года.",sections:[{h:"1. Общие положения",blocks:["Настоящая Политика в отношении обработки персональных данных (далее — \xabПолитика\xbb) определяет порядок обработки и защиты персональных данных пользователей сайта iroxtech.ru.","Оператор персональных данных:","Физическое лицо, сайт iroxtech.ru","E-mail: hello@iroxtech.ru","Сайт: iroxtech.ru","Настоящая Политика разработана в соответствии с Федеральным законом от 27.07.2006 № 152-ФЗ \xabО персональных данных\xbb и иными применимыми нормативными правовыми актами Российской Федерации.","Политика применяется к персональным данным, получаемым Оператором посредством Сайта."]},{h:"2. Основные принципы обработки",blocks:["Оператор осуществляет обработку персональных данных на законной и справедливой основе.","Обработка ограничивается достижением конкретных, заранее определенных и законных целей.","Не допускается обработка персональных данных, несовместимая с целями их сбора.","Состав и объем обрабатываемых персональных данных должны соответствовать заявленным целям обработки.","Оператор принимает необходимые правовые, организационные и технические меры для защиты персональных данных."]},{h:"3. Категории субъектов персональных данных",blocks:["Оператор может обрабатывать персональные данные:",["посетителей и пользователей Сайта;","физических лиц, направляющих обращения посредством Сайта;","представителей и работников потенциальных клиентов, партнеров и контрагентов, самостоятельно предоставляющих свои данные посредством Сайта."]]},{h:"4. Цели обработки и состав данных",blocks:["При использовании формы \xabПришлите видео операции\xbb персональные данные обрабатываются для:",["приема и рассмотрения обращения;","обратной связи с пользователем;","анализа описанной или показанной производственной, складской или логистической операции;","предварительной оценки возможности ее роботизации и/или автоматизации;","определения возможного типа решения;","получения необходимых для оценки исходных данных;","подготовки и направления пользователю информации по его запросу;","дальнейшего взаимодействия по инициативе пользователя."],"Для указанных целей могут обрабатываться:",["имя;","наименование компании и сведения о месте работы;","телефон;","идентификатор/имя пользователя в Telegram;","e-mail;","текст обращения и описание операции;","сведения, содержащиеся в добровольно загружаемом видео;","иные сведения, добровольно предоставленные пользователем в обращении."]]},{h:"5. Правовые основания обработки",blocks:["Оператор обрабатывает персональные данные при наличии предусмотренных законодательством Российской Федерации правовых оснований.","При направлении формы на Сайте таким основанием, в частности, является согласие субъекта персональных данных на обработку его персональных данных.","В случаях, предусмотренных законодательством Российской Федерации, обработка может осуществляться на иных законных основаниях."]},{h:"6. Порядок и способы обработки",blocks:["Оператор может осуществлять:","сбор, запись, систематизацию, накопление, хранение, уточнение, извлечение, использование, предоставление в предусмотренных законом случаях, блокирование, удаление и уничтожение персональных данных.","Обработка может осуществляться с использованием средств автоматизации и без использования таких средств.","Оператор не раскрывает персональные данные третьим лицам без законного основания.","Для технического функционирования Сайта, информационных систем, электронной почты, хранения файлов и обработки обращений Оператор может привлекать третьих лиц и поручать им обработку персональных данных при соблюдении требований законодательства Российской Федерации."]},{h:"7. Видеоматериалы",blocks:["Пользователь может добровольно предоставить видео производственной, складской или логистической операции.","Такие материалы используются для анализа соответствующей операции и оценки возможности ее роботизации и/или автоматизации.","Если видео содержит персональные данные третьих лиц, пользователь, направляющий соответствующие материалы, должен иметь законные основания для их передачи Оператору.","Оператор не использует изображения людей или записи их голоса из таких материалов для установления личности, если иное отдельно не предусмотрено соответствующим законным основанием."]},{h:"8. Сроки хранения и прекращение обработки",blocks:["Персональные данные хранятся не дольше, чем этого требуют цели их обработки, если иной срок хранения не предусмотрен законодательством Российской Федерации или применимым договором.","При достижении целей обработки, отзыве согласия или наступлении иных предусмотренных законодательством оснований Оператор прекращает обработку и осуществляет удаление или уничтожение персональных данных в порядке и сроки, предусмотренные законодательством Российской Федерации, если отсутствуют основания для продолжения обработки."]},{h:"9. Защита персональных данных",blocks:["Оператор принимает необходимые и достаточные правовые, организационные и технические меры для защиты персональных данных от неправомерного или случайного доступа, уничтожения, изменения, блокирования, копирования, предоставления, распространения, а также иных неправомерных действий.","Доступ к персональным данным предоставляется только в объеме, необходимом для выполнения соответствующих задач."]},{h:"10. Права субъекта персональных данных",blocks:["Субъект персональных данных вправе получать предусмотренную законодательством информацию об обработке своих персональных данных, требовать их уточнения, блокирования или уничтожения при наличии предусмотренных законом оснований, а также отозвать ранее предоставленное согласие.","Обращения по вопросам обработки персональных данных направляются по адресу:","hello@iroxtech.ru"]},{h:"11. Актуализация Политики",blocks:["Оператор вправе актуализировать настоящую Политику при изменении порядка обработки персональных данных, используемых на Сайте сервисов или требований законодательства.","Актуальная редакция Политики постоянно доступна по адресу:","https://iroxtech.ru/privacy"]}]}},en:{consent:{title:"CONSENT TO THE PROCESSING OF PERSONAL DATA",updated:"Version dated 3 October 2026.",intro:["I, as a user of the iroxtech.ru website (the “Website”), hereby freely, of my own will and in my own interest, give my specific, informed, conscious and unambiguous consent to the personal data operator of the iroxtech.ru website, e-mail: hello@iroxtech.ru (the “Operator”), to process my personal data under the following terms."],sections:[{h:"1. Purposes of Personal Data Processing",blocks:["Personal data is processed for the following purposes:",["receiving and reviewing my inquiry;","contacting me regarding my inquiry;","carrying out a preliminary assessment of the possibility of robotizing and/or automating the manufacturing, warehouse or logistics operation described or demonstrated by me;","determining a potentially suitable type of robotic solution;","requesting and clarifying the information required for such assessment;","preparing and sending me a preliminary assessment, proposal or other information related to my inquiry;","organizing further communication and negotiations initiated by me."],"This Consent does not provide for the use of my contact details for advertising or marketing communications unrelated to the inquiry submitted by me."]},{h:"2. Personal Data",blocks:["This Consent applies to the following personal data that I voluntarily provide through the Website:",["name;","company name and information about my place of work, if provided;","telephone number;","Telegram username or identifier, if provided;","e-mail address;","information contained in the description of the operation;","other personal data voluntarily included by me in my inquiry;","personal data that may be contained in a video file voluntarily uploaded by me."]]},{h:"3. Uploaded Video Files",blocks:["I understand that a video file submitted by me may contain images of individuals, voices or other information relating to identifiable individuals.","I confirm that where materials submitted by me contain personal data of third parties, I have the necessary lawful grounds to provide such materials to the Operator.","The Operator uses uploaded video files for the purpose of analyzing a manufacturing, warehouse or logistics operation and preparing a preliminary assessment of the possibility of its robotization and/or automation.","The Operator does not process images of individuals or voice recordings contained in such videos for the purpose of identifying a person unless this has been separately agreed with the relevant data subject or is otherwise permitted by applicable law."]},{h:"4. Personal Data Processing Operations",blocks:["I consent to the Operator carrying out the following operations with my personal data:","collection, recording, systematization, accumulation, storage, updating and modification, retrieval, use, provision to persons engaged by the Operator to technically support the Website and process the inquiry, blocking, deletion and destruction.","Personal data may be processed using automated means or without the use of automated means."]},{h:"5. Data Transfers and Processing by Service Providers",blocks:["The Operator may engage third parties to process personal data where such parties provide services necessary for the operation of the Website, hosting, information systems, e-mail communications, file storage and processing of inquiries.","Such processing shall be limited to what is necessary for the relevant purpose and shall be carried out subject to the requirements of applicable personal data legislation.","Personal data may otherwise be transferred to third parties only where a lawful basis for such transfer exists."]},{h:"6. Processing Period",blocks:["Personal data shall be processed until the purposes for which it was collected have been achieved or until this Consent is withdrawn, unless the Operator has another lawful basis to continue processing under applicable legislation.","Upon achievement of the purposes of processing, withdrawal of Consent or occurrence of another applicable legal ground, the processing shall be terminated and personal data shall be deleted, destroyed or anonymized in accordance with the procedure and time limits established by applicable law."]},{h:"7. Withdrawal of Consent",blocks:["I may withdraw this Consent by sending a request to the Operator at:","hello@iroxtech.ru","The request should contain sufficient information to enable the Operator to identify the personal data and inquiry to which the withdrawal relates.","Following receipt of the withdrawal, the Operator shall cease processing and delete or destroy the relevant personal data in accordance with applicable law unless there is a lawful basis for continuing the processing without my consent."]},{h:"8. Confirmation of Consent",blocks:["By actively selecting the relevant checkbox on the Website and submitting the form, I confirm that I have read this Consent, understand its contents and consent to the processing of my personal data under the terms set out herein."]}]},privacy:{title:"PERSONAL DATA PROCESSING POLICY",updated:"Version dated 3 October 2026.",sections:[{h:"1. General Provisions",blocks:["This Personal Data Processing Policy (the “Policy”) establishes the procedure for processing and protecting the personal data of users of the iroxtech.ru website.","Personal Data Operator:","An individual, website iroxtech.ru","E-mail: hello@iroxtech.ru","Website: iroxtech.ru","This Policy has been prepared in accordance with Federal Law No. 152-FZ of 27 July 2006 “On Personal Data” and other applicable laws and regulations of the Russian Federation.","This Policy applies to personal data obtained by the Operator through the Website."]},{h:"2. Basic Principles of Processing",blocks:["The Operator processes personal data lawfully and fairly.","Processing is limited to achieving specific, predetermined and lawful purposes.","Personal data shall not be processed in a manner incompatible with the purposes for which it was collected.","The scope and nature of the personal data processed shall correspond to the stated purposes of processing.","The Operator takes necessary legal, organizational and technical measures to protect personal data."]},{h:"3. Categories of Data Subjects",blocks:["The Operator may process personal data relating to:",["visitors and users of the Website;","individuals submitting inquiries through the Website;","representatives and employees of prospective customers, partners and counterparties who voluntarily provide their personal data through the Website."]]},{h:"4. Purposes and Categories of Personal Data",blocks:["When using the “Send us a video of your operation” form, personal data is processed for:",["receiving and reviewing an inquiry;","contacting the user;","analyzing the manufacturing, warehouse or logistics operation described or demonstrated by the user;","carrying out a preliminary assessment of the possibility of robotization and/or automation;","determining a potentially suitable type of solution;","obtaining and clarifying information necessary for the assessment;","preparing and sending information requested by the user;","further communication initiated by the user."],"For these purposes, the Operator may process:",["name;","company name and place-of-work information;","telephone number;","Telegram username or identifier;","e-mail address;","inquiry text and description of the operation;","information contained in a voluntarily uploaded video;","other information voluntarily provided by the user in the inquiry."]]},{h:"5. Legal Grounds for Processing",blocks:["The Operator processes personal data where a legal basis provided for by the legislation of the Russian Federation exists.","When a form is submitted through the Website, such legal basis includes, in particular, the data subject’s consent to the processing of personal data.","Where provided by applicable law, processing may also be carried out on other lawful grounds."]},{h:"6. Processing Procedures and Methods",blocks:["The Operator may perform the following operations:","collection, recording, systematization, accumulation, storage, updating, retrieval, use, provision where permitted by law, blocking, deletion and destruction of personal data.","Processing may be carried out using automated means or without the use of automated means.","The Operator does not disclose personal data to third parties without a lawful basis.","For the technical operation of the Website, information systems, e-mail, file storage and processing of inquiries, the Operator may engage third parties and entrust them with the processing of personal data subject to compliance with applicable personal data legislation."]},{h:"7. Video Materials",blocks:["A user may voluntarily provide a video of a manufacturing, warehouse or logistics operation.","Such materials are used to analyze the relevant operation and assess the possibility of its robotization and/or automation.","Where a video contains personal data of third parties, the user submitting the materials must have a lawful basis for providing such data to the Operator.","The Operator does not use images of individuals or recordings of their voices contained in such materials for the purpose of identifying those individuals unless a separate lawful basis exists."]},{h:"8. Retention and Termination of Processing",blocks:["Personal data shall not be retained for longer than necessary for the purposes for which it is processed unless another retention period is required by the legislation of the Russian Federation or an applicable agreement.","Upon achievement of the purposes of processing, withdrawal of consent or occurrence of other grounds established by law, the Operator shall cease processing and delete or destroy personal data in accordance with applicable requirements unless there is a lawful basis for continued processing."]},{h:"9. Personal Data Protection",blocks:["The Operator takes necessary and sufficient legal, organizational and technical measures to protect personal data against unauthorized or accidental access, destruction, alteration, blocking, copying, provision, distribution and other unlawful actions.","Access to personal data is provided only to the extent necessary to perform the relevant functions."]},{h:"10. Rights of Data Subjects",blocks:["A data subject has the right to obtain information concerning the processing of their personal data as provided by applicable law, request correction, blocking or destruction of personal data where legally permitted, and withdraw previously given consent.","Requests concerning personal data processing may be sent to:","hello@iroxtech.ru"]},{h:"11. Updates to this Policy",blocks:["The Operator may update this Policy where the personal data processing procedures, services used by the Website or applicable legal requirements change.","The current version of this Policy is available at:","https://iroxtech.ru/en/privacy"]}]}},zh:{consent:{title:"个人数据处理同意书",updated:"版本日期：2026年10月3日",intro:["本人作为 iroxtech.ru 网站（以下简称“网站”）的用户，自愿、自主并基于本人利益，明确、具体、知情且无歧义地同意 iroxtech.ru 网站的个人数据运营者（电子邮箱：hello@iroxtech.ru，以下简称“运营者”）按照以下条件处理本人的个人数据。"],sections:[{h:"1. 个人数据处理目的",blocks:["个人数据将用于以下目的：",["接收和审阅本人提交的咨询或申请；","就本人提交的咨询与本人取得联系；","对本人描述或展示的生产、仓储或物流作业进行机器人化和/或自动化可行性的初步评估；","确定可能适用的机器人解决方案类型；","获取和澄清进行评估所需的信息；","准备并向本人发送初步评估、方案或与本人咨询相关的其他信息；","根据本人的主动请求开展进一步沟通和洽谈。"],"本同意书不包括将本人的联系方式用于与本人所提交咨询无关的广告或营销信息发送。"]},{h:"2. 个人数据范围",blocks:["本同意适用于本人通过网站自愿提供的以下个人数据：",["姓名；","公司名称以及工作单位信息（如本人提供）；","电话号码；","Telegram 用户名或账号标识（如本人提供）；","电子邮箱地址；","本人在作业描述中提供的信息；","本人在咨询中自愿提供的其他个人数据；","本人自愿上传的视频文件中可能包含的个人数据。"]]},{h:"3. 上传的视频文件",blocks:["本人理解，本人提交的视频文件可能包含个人图像、声音或其他与自然人有关的信息。","如果本人提交的材料包含第三方个人数据，本人确认具有向运营者提供该等材料所需的合法依据。","运营者仅为分析生产、仓储或物流作业，以及对其机器人化和/或自动化的可能性进行初步评估而使用上传的视频文件。","除非已与相关个人数据主体另行达成约定，或适用法律另有合法依据，运营者不会为了识别个人身份而处理视频中包含的个人图像或声音记录。"]},{h:"4. 对个人数据实施的操作",blocks:["本人同意运营者对本人的个人数据实施以下操作：","收集、记录、系统化、积累、存储、更新和修改、提取、使用、向运营者为网站技术运行和处理咨询而聘用的相关人员或服务提供商提供、限制处理、删除和销毁。","个人数据可以使用自动化方式处理，也可以不使用自动化方式处理。"]},{h:"5. 数据提供及委托处理",blocks:["为确保网站、托管服务、信息系统、电子邮件、文件存储以及咨询处理的正常运行，运营者可委托第三方处理必要范围内的个人数据。","相关处理应仅限于实现相应目的所必需的范围，并遵守适用的个人数据保护法律要求。","在其他情况下，只有存在合法依据时，运营者才会向第三方提供个人数据。"]},{h:"6. 处理期限",blocks:["个人数据将处理至收集该等数据的目的实现之日，或本人撤回本同意之日，以较早发生者为准；但适用法律允许运营者在无需本人同意的情况下继续处理的除外。","在处理目的实现、同意被撤回或发生法律规定的其他情形后，运营者将按照适用法律规定的程序和期限停止处理，并删除、销毁或匿名化相关个人数据。"]},{h:"7. 撤回同意",blocks:["本人有权通过以下电子邮箱向运营者发送申请，以撤回本同意：","hello@iroxtech.ru","申请中建议提供足以使运营者确定撤回请求所涉及的个人数据和咨询的信息。","收到撤回申请后，如不存在无需本人同意即可继续处理的其他合法依据，运营者将按照适用法律规定停止处理并删除或销毁相关个人数据。"]},{h:"8. 同意确认",blocks:["本人通过主动勾选网站表单中的相应复选框并提交表单，即确认本人已阅读并理解本同意书的内容，并同意运营者按照本同意书规定的条件处理本人的个人数据。"]}]},privacy:{title:"个人数据处理政策",updated:"版本日期：2026年10月3日",sections:[{h:"1. 一般规定",blocks:["本《个人数据处理政策》（以下简称“本政策”）规定 iroxtech.ru 网站用户个人数据的处理和保护程序。","个人数据运营者：","自然人，网站 iroxtech.ru","电子邮箱：hello@iroxtech.ru","网站：iroxtech.ru","本政策依据俄罗斯联邦2006年7月27日第152-FZ号联邦法律《个人数据法》以及俄罗斯联邦其他适用的法律法规制定。","本政策适用于运营者通过网站获取的个人数据。"]},{h:"2. 个人数据处理的基本原则",blocks:["运营者以合法、公平的方式处理个人数据。","个人数据处理仅限于实现具体、预先确定且合法的目的。","不得以与收集目的不相符的方式处理个人数据。","所处理个人数据的内容和范围应与所声明的处理目的相符。","运营者采取必要的法律、组织和技术措施保护个人数据。"]},{h:"3. 个人数据主体类别",blocks:["运营者可能处理以下人员的个人数据：",["网站访问者和用户；","通过网站提交咨询或申请的自然人；","通过网站自愿提供个人数据的潜在客户、合作伙伴及交易相对方的代表或员工。"]]},{h:"4. 处理目的及个人数据范围",blocks:["用户使用“发送您的作业视频”表单时，个人数据将用于：",["接收和审阅咨询；","与用户进行联系；","分析用户描述或展示的生产、仓储或物流作业；","初步评估机器人化和/或自动化的可行性；","确定可能适用的解决方案类型；","获取和澄清评估所需的信息；","准备并向用户发送其所请求的信息；","根据用户主动提出的需求进行后续沟通。"],"为实现上述目的，运营者可能处理：",["姓名；","公司名称及工作单位信息；","电话号码；","Telegram 用户名或账号标识；","电子邮箱地址；","咨询内容及作业描述；","用户自愿上传的视频中包含的信息；","用户在咨询中自愿提供的其他信息。"]]},{h:"5. 个人数据处理的法律依据",blocks:["运营者在俄罗斯联邦法律规定的合法依据存在时处理个人数据。","用户通过网站提交表单时，相关法律依据尤其包括个人数据主体对其个人数据处理所作出的同意。","在适用法律规定的情况下，运营者也可以基于其他合法依据处理个人数据。"]},{h:"6. 处理程序和方式",blocks:["运营者可能对个人数据实施以下操作：","收集、记录、系统化、积累、存储、更新、提取、使用、在法律允许的情况下提供、限制处理、删除和销毁。","个人数据可以使用自动化方式处理，也可以不使用自动化方式处理。","没有合法依据时，运营者不会向第三方披露个人数据。","为确保网站、信息系统、电子邮件、文件存储及咨询处理的技术运行，运营者可聘用第三方，并在遵守适用个人数据法律要求的前提下委托其处理个人数据。"]},{h:"7. 视频材料",blocks:["用户可以自愿提供生产、仓储或物流作业的视频。","该等材料用于分析相关作业，并评估其机器人化和/或自动化的可能性。","如果视频包含第三方个人数据，提交材料的用户应具有向运营者提供该等数据的合法依据。","除非存在单独的合法依据，运营者不会为了识别相关个人身份而使用材料中包含的个人图像或声音记录。"]},{h:"8. 保存期限及终止处理",blocks:["除俄罗斯联邦法律或适用合同规定其他保存期限外，个人数据的保存期限不得超过实现处理目的所必需的期限。","在处理目的实现、同意被撤回或出现法律规定的其他终止处理依据时，如不存在继续处理的合法依据，运营者将停止处理，并按照适用法律规定的程序删除或销毁个人数据。"]},{h:"9. 个人数据保护",blocks:["运营者采取必要且充分的法律、组织和技术措施，保护个人数据免遭未经授权或意外的访问、销毁、修改、限制、复制、提供、传播以及其他非法行为。","仅在履行相关职责所必需的范围内提供对个人数据的访问权限。"]},{h:"10. 个人数据主体的权利",blocks:["个人数据主体有权按照适用法律获取与其个人数据处理有关的信息；在法律规定的情况下要求更正、限制处理或删除个人数据；以及撤回此前作出的同意。","有关个人数据处理的请求可发送至：","hello@iroxtech.ru"]},{h:"11. 本政策的更新",blocks:["当个人数据处理程序、网站使用的服务或适用法律要求发生变化时，运营者可以更新本政策。","本政策的最新版本可通过以下地址查阅：","https://iroxtech.ru/zh/privacy"]}]}}};var n=t(8670);function l(e){let{text:o}=e;return String(o).split(/(hello@iroxtech\.ru|https:\/\/iroxtech\.ru[^\s)]*)/g).map((e,o)=>"hello@iroxtech.ru"===e?(0,a.jsx)("a",{href:"mailto:hello@iroxtech.ru",children:"hello@iroxtech.ru"},o):e.startsWith("https://iroxtech.ru")?(0,a.jsx)("a",{href:e,children:e},o):(0,a.jsx)("span",{children:e},o))}function c(e){let{blocks:o}=e;return o.map((e,o)=>Array.isArray(e)?(0,a.jsx)("ul",{children:e.map(e=>(0,a.jsxs)("li",{children:["— ",(0,a.jsx)(l,{text:e})]},e))},o):(0,a.jsx)("p",{children:(0,a.jsx)(l,{text:e})},o))}function h(e){let{lang:o,doc:t}=e,l=r.C[o],h=i[o][t],d={ru:(0,r.rN)("ru",t),en:(0,r.rN)("en",t),zh:(0,r.rN)("zh",t)};return(0,s.useEffect)(()=>{document.documentElement.lang="zh"===o?"zh-Hans":o,localStorage.setItem("irox-lang",o)},[o]),(0,a.jsxs)("main",{className:"legalPage",children:[(0,a.jsx)(n.DW,{t:l,lang:o,hrefs:d,home:"/"}),(0,a.jsx)("div",{className:"legalWrap",children:(0,a.jsxs)("article",{className:"legal",children:[(0,a.jsx)("a",{className:"legalBack",href:"/",children:l.back}),(0,a.jsx)("h1",{children:h.title}),(0,a.jsx)("p",{className:"legalDate",children:h.updated}),(0,a.jsx)(c,{blocks:h.intro||[]}),h.sections.map(e=>(0,a.jsxs)("section",{children:[(0,a.jsx)("h2",{children:e.h}),(0,a.jsx)(c,{blocks:e.blocks})]},e.h))]})}),(0,a.jsx)(n.D1,{t:l,lang:o,logoHref:"/"})]})}}}]);